%[text] %[text:anchor:T_1FFD3858] # Longitudinal Vehicle - Simulation Case
%[text] %[text:anchor:H_1B376934] ## Accelerate
model_name = "HarnessModel_Vehicle1D";
load_system(model_name)

Vehicle1D_Basic_params

loadLUTData_Vehicle1D_Accelerate

initial.vehicle_speed_kph = 0;

sim_in = Simulink.SimulationInput(model_name);
sim_in = setBlockParameter(sim_in, model_name + "/Inputs", ReferencedSubsystem = "Inputs_Vehicle1D_LookupTables_refsub");
sim_in = setBlockParameter(sim_in, model_name + "/Longitudinal Vehicle", ReferencedSubsystem = "Vehicle1D_Basic_refsub");
sim_in = setModelParameter(sim_in, StopTime = "300");
applyToModel(sim_in)
sim_out = sim(sim_in);

result = extractTimetable(sim_out.logsout);

signal_names = [
  "Axle torque input"
  "Brake force"
  "Road inclination"
  "Road grade"
  "G force"
  "Vehicle speed kph"
  "Vehicle speed mph"
  "Axle speed"
  ];

for k = 1 : numel(signal_names) %[output:group:7ff97bfe]
  fig = bevutil1.SignalUtil.plotTimedData(TimedData = result, SignalName = signal_names(k)); %[output:24e3c578] %[output:433980aa] %[output:9f3f964b] %[output:726e2cec] %[output:3dbfeb97] %[output:47a35fa0] %[output:4faf5d60] %[output:455744b3]
  fig.Position(4) = 200;  % height
end  % for %[output:group:7ff97bfe]
